# Generated by build.py from recipe.yml for recipe ws-receive-a-large-file-in-frames. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir site
head -c 200000 /dev/urandom > site/big.bin
head -c 65536 /dev/urandom > site/at-limit.bin
head -c 65537 /dev/urandom > site/over-limit.bin
surl -v --log-file surl.log --directory site ws://127.0.0.1:8080/ &
sleep 1
curl -s -o got.bin ws://127.0.0.1:8080/big.bin && cmp got.bin site/big.bin && echo identical
kill $(jobs -p)
